import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def evaluate_N(x, y, z):
    # Assumes x, y, z are positive integers for this initial search
    try:
        term1 = y**x
        term2 = z**y
        term3 = x**z
        N = term1 * term2 * term3
        return N
    except OverflowError:
        # Handle cases where N is too large to compute easily
        return float('inf')

# Brute force search for small positive integers (x, y, z)
K = 7 # Search up to 7 for a reasonable start
good_triples = []

for x in range(1, K + 1):
    for y in range(1, K + 1):
        for z in range(1, K + 1):
            N = evaluate_N(x, y, z)
            if N != float('inf') and is_prime(N):
                S = x**2 + y**2 + z**2
                good_triples.append({'triple': (x, y, z), 'S': S})

# Sort the triples based on S
good_triples.sort(key=lambda t: t['S'])

print("Found good triples up to K=7:")
for i, triple in enumerate(good_triples):
    print(f"k={i+1}: Triple={triple['triple']}, S={triple['S']}")

