import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

candidates = {
    'A': 100491,
    'B': 108902,
    'C': 51531,
    'D': 109563
}

print("Checking candidates against the form P^2 + 2 where P is prime:")

for label, S in candidates.items():
    diff = S - 2
    if diff <= 0:
        print(f"Candidate {label}: {S}. Difference is non-positive, cannot be P^2 + 2.")
        continue

    sqrt_diff = math.isqrt(diff)

    if sqrt_diff * sqrt_diff == diff:
        P = sqrt_diff
        if is_prime(P):
            print(f"Candidate {label}: {S}. Fits the form P^2 + 2 where P = {P} (prime).")
        else:
            print(f"Candidate {label}: {S}. Fits the form P^2 + 2, but P = {P} is not prime.")
    else:
        print(f"Candidate {label}: {S}. Does not fit the form P^2 + 2.")
